(x, y, t) => {
  const wx1 = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const wy1 = Math.cos(y*0.016-t*0.25)*16 + Math.sin(x*0.02+t*0.33)*11;
  const sx = x+wx1, sy = y+wy1;
  const wx2 = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.03+t*0.35)*6;
  const wy2 = Math.cos(sy*0.028+t*0.45)*7 + Math.sin(sx*0.022-t*0.38)*5;
  const fx = sx+wx2, fy = sy+wy2;
  const cx = 240, cy = 120;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,1.2],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,2.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,3.6],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,4.8],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,6.0],
    [80+Math.sin(t*0.65+3)*70,40+Math.cos(t*0.75+1)*55,0.11,2.1,1.8],
    [400+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.85+4)*45,0.13,1.4,5.2]
  ];
  let act=0,inh=0,cross=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    act+=Math.sin(d*f-t*sp+ph);inh+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);cross+=Math.sin(d*f*1.3-t*sp*0.8+ph*0.5)*0.5;
  }
  act/=8;inh/=8;cross/=8;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2+Math.sin(fx*0.07*Math.cos(t*0.2)+fy*0.05*Math.sin(t*0.3)+t*1.5)*0.15;
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.065-ang*5+t*0.9))*0.3;
  const spiral2=Math.sin(dist*0.035+ang*6+t*1.8)*0.2;
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const feed=act-inh*0.7+bg*0.3+spiral+spiral2*0.5;
  const reaction=Math.tanh(feed*2.2);
  const rd1=Math.tanh((reaction+cross)*1.5);
  const rd2=Math.tanh((reaction-cross*0.5+cell)*1.8);
  const blend=rd1*0.6+rd2*0.25+cell*0.15, v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,85],[18,85,120],[25,140,130],[60,175,110],[160,195,70],[220,185,55],[230,140,60],[210,90,65],[180,55,75],[130,35,70],[75,22,60],[35,15,55],[6,12,52]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.75+Math.sin(rd1*Math.PI)*0.25;
  const edge=Math.abs(rd1)>0.65?1.2:(Math.abs(rd2)>0.7?1.1:1.0);
  const spec=Math.max(0,Math.sin(blend*4+t*2))*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+spec*180)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+spec*160)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+spec*120)|0)
  ];
}
